python3 << 'EOF'
import json
data = json.load(open('/tmp/rpl_fb_posts.json'))

rows_html = []
for d in data:
    rows_html.append(f'''      <tr>
        <td class="num">{d['序號']}</td>
        <td class="time">{d['發布時間']}</td>
        <td class="topic"><a href="{d['連結']}" target="_blank" rel="noopener noreferrer">{d['主題']}</a></td>
        <td class="channel"><span class="badge">{d['發布管道']}</span></td>
        <td class="link"><a href="{d['連結']}" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></td>
      </tr>''')

rows_joined = '\n'.join(rows_html)
total = len(data)
latest = data[-1]['發布時間']
earliest = data[0]['發布時間']

html = f'''<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>結繩領導學 FB貼文紀錄</title>
<style>
:root{{
  --bg:#f4f7fb; --blue-deep:#0b2742; --blue-mid:#174873; --blue:#123a63;
  --muted:#5f6b76; --orange-soft:#ffb25b; --orange:#f28c28;
  --radius-lg:26px; --radius:18px; --text:#1d2a35; --white:#ffffff;
}}
*{{box-sizing:border-box}}
body{{margin:0;font-family:"Noto Sans TC","PingFang TC",-apple-system,sans-serif;background:var(--bg);color:var(--text);padding:24px 16px 60px}}
.wrap{{max-width:1000px;margin:0 auto}}
header{{background:linear-gradient(135deg,var(--blue-deep),var(--blue-mid));color:#fff;border-radius:var(--radius-lg);padding:36px 32px;margin-bottom:24px;box-shadow:0 10px 30px rgba(11,39,66,.18)}}
header h1{{margin:0 0 8px;font-size:26px;font-weight:900}}
header p{{margin:0;color:#cfe0f0;font-size:14px}}
.stats{{display:flex;gap:16px;margin-top:20px;flex-wrap:wrap}}
.stat{{background:rgba(255,255,255,.12);border-radius:var(--radius);padding:12px 20px}}
.stat .n{{font-size:22px;font-weight:900;color:var(--orange-soft)}}
.stat .l{{font-size:12px;color:#cfe0f0}}
.card{{background:var(--white);border-radius:var(--radius-lg);box-shadow:0 8px 24px rgba(11,39,66,.08);overflow:hidden}}
table{{width:100%;border-collapse:collapse;font-size:14px}}
thead th{{background:var(--blue);color:#fff;text-align:left;padding:14px 16px;font-weight:700;position:sticky;top:0}}
tbody tr{{border-bottom:1px solid #eef1f5;transition:.15s}}
tbody tr:hover{{background:#f7fafd}}
tbody td{{padding:14px 16px;vertical-align:top}}
.num{{color:var(--muted);font-weight:700;width:48px}}
.time{{color:var(--muted);white-space:nowrap;width:130px;font-variant-numeric:tabular-nums}}
.topic a{{color:var(--blue-deep);font-weight:700;text-decoration:none;line-height:1.5}}
.topic a:hover{{color:var(--orange);text-decoration:underline}}
.channel{{width:70px}}
.badge{{background:#e8f0fe;color:var(--blue-mid);font-weight:800;font-size:12px;padding:4px 10px;border-radius:999px}}
.link{{width:110px}}
.link a{{color:var(--orange);font-weight:700;text-decoration:none;font-size:13px;white-space:nowrap}}
.link a:hover{{text-decoration:underline}}
.tablewrap{{overflow-x:auto}}
footer{{margin-top:20px;color:var(--muted);font-size:12px;line-height:1.8;padding:0 8px}}
@media(max-width:640px){{
  header{{padding:24px 20px}}
  header h1{{font-size:20px}}
  thead th, tbody td{{padding:10px 10px;font-size:13px}}
}}
</style>
</head>
<body>
<div class="wrap">
  <header>
    <h1>📖 結繩領導學 — FB粉專貼文紀錄</h1>
    <p>整理自 Facebook 粉專後台匯出資料，依發布時間排序，一目瞭然掌握每篇貼文主題與連結。</p>
    <div class="stats">
      <div class="stat"><div class="n">{total}</div><div class="l">總貼文數</div></div>
      <div class="stat"><div class="n">{earliest[:10]}</div><div class="l">最早一篇</div></div>
      <div class="stat"><div class="n">{latest[:10]}</div><div class="l">最新一篇</div></div>
    </div>
  </header>
  <div class="card">
    <div class="tablewrap">
    <table>
      <thead>
        <tr>
          <th>序號</th>
          <th>發布時間</th>
          <th>主題（第一句話）</th>
          <th>管道</th>
          <th>連結</th>
        </tr>
      </thead>
      <tbody>
{rows_joined}
      </tbody>
    </table>
    </div>
  </div>
  <footer>
    資料來源：Facebook 粉專後台匯出的 CSV（{earliest} ～ {latest}）。「主題」欄取自貼文文案的第一句話，「連結」點擊可直接開啟原始貼文。<br>
    ⚠️ 原始 CSV 的「貼文編號」欄位在匯出/以Excel開啟時已被轉成科學記號（如 1.22E+17），精確度已遺失、多筆貼文顯示相同數字，僅供參考，不能當作唯一識別碼——真正能唯一辨識每篇貼文的是「連結」欄位。<br>
    本頁面由軍師（Claude）整理產生，資料如有更新，重新匯出CSV後可再次處理。
  </footer>
</div>
</body>
</html>
'''

with open('/tmp/rpl_fb_posts_index.html', 'w', encoding='utf-8') as f:
    f.write(html)
print("已產出 /tmp/rpl_fb_posts_index.html，長度:", len(html))
EOF

