1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<title>{% block title %}BNI大台南南區{% endblock %}</title>
6	<link rel="preconnect" href="https://fonts.googleapis.com">
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root{
10	    --red:#A22026; --red-dark:#791F1F; --ink:#2A2829; --paper:#FAF7F2;
11	    --line:#E5DFD3; --gold:#B08D57; --sub:#6B665D;
12	  }
13	  *{box-sizing:border-box;margin:0;padding:0;}
14	  body{font-family:"Helvetica Neue",Arial,"PingFang TC","Microsoft JhengHei","Noto Sans TC",sans-serif;color:var(--ink);background:var(--paper);line-height:1.7;}
15	  a{text-decoration:none;color:inherit;}
16	  .wrap{max-width:1120px;margin:0 auto;padding:0 32px;}
17	  header{position:sticky;top:0;background:#fff;border-bottom:1px solid var(--line);z-index:10;}
18	  .navbar{display:flex;align-items:center;justify-content:space-between;padding:18px 0;}
19	  .logo{font-size:20px;font-weight:900;color:var(--red-dark);letter-spacing:1px;}
20	  .logo span{font-weight:400;font-size:13px;color:var(--sub);display:block;margin-top:2px;letter-spacing:2px;}
21	  nav ul{display:flex;gap:32px;list-style:none;font-size:15px;font-weight:500;}
22	  nav a:hover{color:var(--red);}
23	  .btn{display:inline-block;background:var(--red);color:#fff;padding:12px 28px;border-radius:4px;font-weight:700;font-size:14px;letter-spacing:1px;transition:background .2s;border:none;cursor:pointer;}
24	  .btn:hover{background:var(--red-dark);}
25	  .btn-outline{background:transparent;border:2px solid #fff;color:#fff;}
26	  .btn-outline:hover{background:#fff;color:var(--red-dark);}
27	  .badge{display:inline-block;background:var(--gold);color:#fff;padding:6px 18px;border-radius:20px;font-size:13px;font-weight:700;letter-spacing:2px;margin-bottom:20px;}
28	  .hero{background:var(--ink);color:#fff;padding:100px 0 90px;text-align:center;position:relative;}
29	  .hero::after{content:"";position:absolute;bottom:0;left:0;right:0;height:6px;background:var(--red);}
30	  .hero h1{font-size:52px;font-weight:900;letter-spacing:2px;margin-bottom:18px;}
31	  .hero p{font-size:18px;color:#D8D0C0;max-width:600px;margin:0 auto 40px;}
32	  .hero .cta-row{display:flex;gap:16px;justify-content:center;flex-wrap:wrap;}
33	  section{padding:90px 0;}
34	  .section-tag{color:var(--red);font-weight:700;font-size:13px;letter-spacing:3px;text-transform:uppercase;margin-bottom:12px;}
35	  h2{font-size:34px;font-weight:900;margin-bottom:16px;}
36	  .lead{color:var(--sub);font-size:16px;max-width:640px;margin-bottom:56px;}
