39	  .notice-num{width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;font-weight:700;font-size:18px;display:flex;align-items:center;justify-content:center;margin:0 auto 16px;}
40	  .notice-card h3{font-size:16px;font-weight:700;margin-bottom:6px;}
